/**
 * "VERSION TYPES: Major, Minor, Patch, Draft, Snapshot, Release, Hotfix, Experimental,
 * Temporary, AutoGenerated." (docs/PROMPT-005.7H-KNOWLEDGE-VERSIONING.md) — the exact
 * 10-type list from the prompt.
 */
export enum KnowledgeVersionType {
  MAJOR = "major",
  MINOR = "minor",
  PATCH = "patch",
  DRAFT = "draft",
  SNAPSHOT = "snapshot",
  RELEASE = "release",
  HOTFIX = "hotfix",
  EXPERIMENTAL = "experimental",
  TEMPORARY = "temporary",
  AUTO_GENERATED = "autogenerated",
}

/**
 * Version Types whose `versionNumber` must be a strict `major.minor.patch` numeric
 * string — enforced by the Validator's Version Number stage. Judgment call: the prompt
 * names the stage but not the rule; Major/Minor/Patch/Release/Hotfix versions are
 * numbered artifacts, while Draft/Snapshot/Experimental/Temporary/AutoGenerated versions
 * only need a non-empty version label.
 */
export const NUMERIC_KNOWLEDGE_VERSION_TYPES: ReadonlySet<KnowledgeVersionType> = new Set([
  KnowledgeVersionType.MAJOR,
  KnowledgeVersionType.MINOR,
  KnowledgeVersionType.PATCH,
  KnowledgeVersionType.RELEASE,
  KnowledgeVersionType.HOTFIX,
]);
